    private static void writeLineups(AuditSnapshot s)throws IOException{List<List<String>>rows=new ArrayList<>();List<String>h=new ArrayList<>(List.of("lineupId","TOP","JUNGLE","MID","ADC","SUPPORT"));for(var c:CompositionCapability.values())h.add(c.name());for(var p:CompositionPattern.values())h.add(p.name());for(var d:CompositionDeficiency.values())h.add(d.name()+"_PRESENT");for(var d:CompositionDeficiency.values())h.add(d.name()+"_SEVERITY");h.addAll(List.of("physicalShare","magicShare","trueDamageShare","shareApplicable","explanationParity","repeatedEvaluationExact"));rows.add(h);for(var x:s.lineups()){List<String>r=new ArrayList<>(List.of(x.lineupId(),x.keys().get(Position.TOP).stableId(),x.keys().get(Position.JUNGLE).stableId(),x.keys().get(Position.MID).stableId(),x.keys().get(Position.ADC).stableId(),x.keys().get(Position.SUPPORT).stableId()));for(var c:CompositionCapability.values())r.add(num(x.capabilities().get(c)));for(var p:CompositionPattern.values())r.add(num(x.patterns().get(p)));for(var d:CompositionDeficiency.values())r.add(Boolean.toString(x.present().get(d)));for(var d:CompositionDeficiency.values())r.add(num(x.severity().get(d)));r.addAll(List.of(num(x.physicalShare()),num(x.magicShare()),num(x.trueDamageShare()),Boolean.toString(x.shareApplicable()),Boolean.toString(x.explanationParity()),Boolean.toString(x.repeatedEvaluationExact())));rows.add(r);}writeCsv(OUTPUT.resolve("thirty-champion-composition-lineups.csv"),rows);}
