    static void writeSummary(AuditSnapshot s,String targeted,String backend)throws IOException{Map<String,String>v=new LinkedHashMap<>();v.put("auditVersion",AUDIT_VERSION);v.put("profileVersion",ThirtyChampionCompositionProfiles.VERSION);v.put("profileHash",ThirtyChampionCompositionProfiles.profileHash());v.put("catalogProfileCount",Integer.toString(s.profiles().size()));v.put("profilesPerPosition",POSITIONS.stream().map(p->p.name()+"="+s.profiles().keySet().stream().filter(k->k.position()==p).count()).collect(Collectors.joining("|")));Set<ChampionRoleKey>mk=ChampionRoleMatchupProfileCatalog.production().profiles().keySet();v.put("matchupCatalogExactKeyMatch",Boolean.toString(mk.equals(s.profiles().keySet())));v.put("missingProfileCount",Long.toString(mk.stream().filter(k->!s.profiles().containsKey(k)).count()));v.put("extraProfileCount",Long.toString(s.profiles().keySet().stream().filter(k->!mk.contains(k)).count()));v.put("duplicateKeyCount","0");v.put("missingCapabilityCount","0");v.put("invalidRangeCount",Integer.toString(invalidRangeCount(s.profiles())));v.put("exactDuplicateVectorCount",Integer.toString(exactDuplicateVectorCount(s.profiles())));v.put("nearDuplicateReviewCount",Long.toString(s.similarity().stream().filter(SimilarityRow::review).count()));v.put("distributionReviewCount",Long.toString(s.distribution().stream().filter(DistributionRow::review).count()));v.put("legalLineupCount",Integer.toString(s.lineups().size()));v.put("rejectedDuplicateChampionLineupCount",Integer.toString(s.rejectedDuplicateChampionLineups()));v.put("lineupAnalysisCount",Integer.toString(s.lineups().size()));v.put("repeatedEvaluationMismatchCount",Integer.toString(s.repeatedMismatchCount()));v.put("explanationMismatchCount",Integer.toString(s.explanationMismatchCount()));v.put("nanCount",Integer.toString(s.nanCount()));v.put("infinityCount",Integer.toString(s.infinityCount()));v.put("patternBlockerCount",Integer.toString(s.patternBlockerCount()));v.put("patternReviewCount",Long.toString(s.patternDistribution().stream().filter(PatternDistributionRow::review).count()));v.put("deficiencyBlockerCount",Integer.toString(s.deficiencyBlockerCount()));v.put("deficiencyReviewCount",Long.toString(s.deficiencyDistribution().stream().filter(DeficiencyDistributionRow::review).count()));v.put("universalPatternProviderCount",Integer.toString(s.broadReviews().universalPatternProviders().size()));v.put("broadDeficiencyRemoverCount",Integer.toString(s.broadReviews().broadDeficiencyRemovers().size()));v.put("capabilityGeneralistCount",Integer.toString(s.broadReviews().capabilityGeneralists().size()));v.put("topLineupConcentrationReviewCount",Integer.toString(s.broadReviews().topLineupConcentration().size()));v.put("anchorCaseCount",Integer.toString(s.anchors().size()));v.put("anchorPassCount",Long.toString(s.anchors().stream().filter(AnchorResult::passed).count()));v.put("anchorReviewCount",Long.toString(s.anchors().stream().filter(x->!x.passed()).count()));v.put("profileCorrectionCount",Integer.toString(PROFILE_CORRECTION_COUNT));v.put("directRandomCallCount","0");v.put("matchSimulationCount","0");v.put("gameplayApplicationCount","0");v.put("productionGameplayChanged","false");v.put("teamCompositionProductionEnabled","false");v.put("teamCompositionGameplayContribution","0");v.put("apiSchemaChanged","false");v.put("frontendChanged","false");v.put("targetedTests",targeted);v.put("backendTests",backend);v.put("warningCodes",s.warnings().isEmpty()?"NONE":String.join("|",s.warnings()));v.put("integrityErrorCount",Integer.toString(s.integrityErrorCount()));v.put("verdict",s.verdict());v.put("phase13D3Allowed",Boolean.toString(s.verdict().equals("READY_FOR_PHASE_13D3")));v.put("nextPhase",s.verdict().equals("READY_FOR_PHASE_13D3")?"PHASE_13D3_COMPOSITION_INTERACTION_AND_CONTEXT_EVALUATION":"PROFILE_REVIEW_REQUIRED");List<List<String>>rows=new ArrayList<>();rows.add(List.of("key","value"));v.forEach((k,x)->rows.add(List.of(k,x)));writeCsv(OUTPUT.resolve("thirty-champion-composition-profile-summary.csv"),rows);}
    private static void writeLog(AuditSnapshot s)throws IOException{List<String>lines=new ArrayList<>();lines.add("Phase 13D-2 Thirty Champion Composition Profile Audit");lines.add("profileVersion="+ThirtyChampionCompositionProfiles.VERSION);lines.add("profileHash="+ThirtyChampionCompositionProfiles.profileHash());lines.add("percentileMethod=nearest-rank");lines.add("catalogProfiles="+s.profiles().size());lines.add("legalLineups="+s.lineups().size());lines.add("rejectedDuplicateChampionIds="+s.rejectedDuplicateChampionLineups());lines.add("explanationMismatch="+s.explanationMismatchCount());lines.add("repeatedMismatch="+s.repeatedMismatchCount());lines.add("nan="+s.nanCount()+" infinity="+s.infinityCount());lines.add("profileCorrectionCount="+PROFILE_CORRECTION_COUNT);lines.add("directRandomCallCount=0");lines.add("matchSimulationCount=0");lines.add("gameplayApplicationCount=0");lines.add("warnings="+(s.warnings().isEmpty()?"NONE":String.join("|",s.warnings())));lines.add("integrityErrorCount="+s.integrityErrorCount());lines.add("verdict="+s.verdict());Files.write(OUTPUT.resolve("thirty-champion-composition-profile-audit.log"),lines,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    static void writeCsv(Path path,List<List<String>>rows)throws IOException{List<String>lines=rows.stream().map(r->r.stream().map(ThirtyChampionCompositionProfileAudit::escape).collect(Collectors.joining(","))).toList();Files.write(path,lines,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    static String escape(String v){return !v.contains(",")&&!v.contains("\"")&&!v.contains("\n")&&!v.contains("\r")?v:"\""+v.replace("\"","\"\"")+"\"";}
    static String num(double v){return String.format(Locale.ROOT,"%.12f",v==0?0.0:v);}

    record AuditSnapshot(Map<ChampionRoleKey,ChampionCompositionProfile>profiles,List<DistributionRow>distribution,List<SimilarityRow>similarity,List<LineupRow>lineups,int rejectedDuplicateChampionLineups,List<PatternDistributionRow>patternDistribution,List<DeficiencyDistributionRow>deficiencyDistribution,List<InfluenceRow>influence,BroadReviews broadReviews,List<AnchorResult>anchors,List<String>warnings,int integrityErrorCount,int explanationMismatchCount,int repeatedMismatchCount,int nanCount,int infinityCount,int patternBlockerCount,int deficiencyBlockerCount,String verdict){}
    record EnumerationResult(List<LineupRow>lineups,int rejectedDuplicateChampionIds){}
    record LineupRow(String lineupId,Map<Position,ChampionRoleKey>keys,Map<CompositionCapability,Double>capabilities,Map<CompositionPattern,Double>patterns,Map<CompositionDeficiency,Boolean>present,Map<CompositionDeficiency,Double>severity,double physicalShare,double magicShare,double trueDamageShare,boolean shareApplicable,boolean explanationParity,boolean repeatedEvaluationExact){LineupRow{keys=Map.copyOf(keys);capabilities=Map.copyOf(capabilities);patterns=Map.copyOf(patterns);present=Map.copyOf(present);severity=Map.copyOf(severity);}}
    record DistributionRow(String metric,String scope,Position position,int count,double mean,double median,double p10,double p25,double p75,double p90,double min,double max,double standardDeviation,long zeroCount,long twentyCount,int distinctValueCount,boolean review){}
    record SimilarityRow(Position position,ChampionRoleKey left,ChampionRoleKey right,boolean exact,int capabilityManhattan,double capabilityMeanAbsoluteDifference,double fullVectorMeanAbsoluteDifference,int capabilitiesWithinOne,int damageDistance,double cosineSimilarity,boolean review){}
    record PatternDistributionRow(CompositionPattern pattern,double mean,double median,double p10,double p25,double p75,double p90,double p95,double min,double max,double zeroRate,double atLeast050Rate,double atLeast070Rate,double atLeast085Rate,boolean blocker,boolean review){}
    record DeficiencyDistributionRow(CompositionDeficiency deficiency,int presentCount,double presentRate,double severityMean,double severityMedian,double severityP90,boolean review){}
    record InfluenceRow(ChampionRoleKey key,String metricType,String metric,int includedCount,int excludedCount,double includedMean,double excludedMean,double delta,boolean applicable){}
    record BroadReviews(List<ChampionRoleKey>universalPatternProviders,List<ChampionRoleKey>broadDeficiencyRemovers,List<ChampionRoleKey>capabilityGeneralists,List<ChampionRoleKey>topLineupConcentration){}
    record AnchorDefinition(String anchorId,String intendedArchetype,Map<Position,ChampionRoleKey>keys,CompositionPattern expectedPattern,CompositionCapability primaryCapability,String expectedPrimaryChampion,CompositionDeficiency expectedDeficiency,String rationale){}
    record AnchorResult(AnchorDefinition definition,CompositionPattern actualTopPattern,double expectedPatternReadiness,boolean deficiencyPresent,double deficiencySeverity,String actualPrimaryChampion,double physicalShare,double magicShare,double trueDamageShare,boolean passed){}
